import os, json
paths=open('/tmp/publish_list.txt').read().split('\n')
total=0; tops={}
missing=0
for p in paths:
    if not os.path.exists(p): missing+=1; continue
    s=os.path.getsize(p); total+=s
    d=p.split('/')[0]; tops[d]=tops.get(d,0)+s
print("missing:", missing)
for d,s in sorted(tops.items(), key=lambda x:-x[1])[:12]: print(f"{s/1024/1024:9.2f} MB  {d}")
print(f"{total/1024/1024:9.2f} MB  TOTAL on disk")
EOF"}

