/// gitignore semantics for the anchored dir/file patterns .pubignore uses:
/// last matching rule wins per path prefix; once a directory is ignored its
/// subtree is ignored too (no re-inclusion from below — the `dir/*` +
/// `!dir/kept` allowlist idiom works because `*` matches the child, not the
/// parent).
bool _ignoredByPubIgnore(List<_PubIgnoreRule> rules, String path, bool isDir) {
  var ignored = false;
  final parts = path.split('/');
  for (var i = 1; i <= parts.length; i++) {
    if (ignored) return true; // inside an ignored dir — nothing re-includes
    final prefix = parts.sublist(0, i).join('/');
    final isDirPrefix = i < parts.length;
    for (final r in rules) {
      if (r.matches(prefix, isDirPrefix)) ignored = !r.negated;
    }
  }
  return ignored;
}

/// Would pub's payload (git-tracked files ∩ .pubignore) carry [file]?
bool _publishedByPub(String file) => !_ignoredByPubIgnore(_pubIgnoreRules(), file, false);
